import {RaceTouchControls} from './ui/RaceTouchControls.js';
import {canPlayMission,lockedMessage} from './core/CampaignAccess.js';
import {AudioToggles} from './ui/AudioToggles.js';
import {GameTouchGuard} from './core/GameTouchGuard.js';
import {Soundtrack} from './audio/Soundtrack.js';
import {JourneyMap} from './ui/JourneyMap.js';
import {FullscreenController} from './ui/FullscreenController.js';
import {MISSIONS} from './data/campaign.js';
import {EventBus} from './core/EventBus.js';
import {SaveManager} from './core/SaveManager.js';
import {GBAInputController} from './core/GBAInputController.js';
import {VoiceStore} from './audio/VoiceStore.js';
import {SoundAndVoiceManager} from './audio/SoundAndVoiceManager.js';
import {UIManager} from './ui/UIManager.js';
import {GameScene} from './world/GameScene.js';

export class ClickGame{
 async init(){this.bus=new EventBus();this.save=new SaveManager();this.settings=this.save.settings();this.voiceStore=await new VoiceStore().init();this.audio=new SoundAndVoiceManager(this.bus,this.voiceStore,this.settings);this.input=new GBAInputController((onlyPause=false)=>{if(!this.playing)return;if(this.ui.dialog.open){if(!onlyPause)this.ui.close();}else this.ui.open('settings');},()=>{if(!this.playing)return;if(this.ui.dialog.open&&this.ui.tab==='journal')this.ui.close();else this.ui.open('journal');});this.ui=new UIManager(this);this.music=new Soundtrack(this);this.playing=false;this.game=null;this.scene=null;this.selectedMission=1;this.fullscreen=new FullscreenController(this);this.raceControls=new RaceTouchControls(this);this.journey=new JourneyMap(this);document.querySelector('#quick-journal').onclick=()=>this.ui.open('journal');document.querySelector('#home-enemies').onclick=()=>this.ui.open('enemies');document.querySelector('#home-hideout').onclick=()=>this.start(false,null,true);document.querySelector('#home-world').onclick=()=>this.ui.open('world');
 document.querySelector('#start-game').onclick=()=>this.start(false);document.querySelector('#continue-game').onclick=()=>this.start(true);document.querySelector('#home-options').onclick=()=>this.ui.open('settings');document.querySelector('#home-powerups').onclick=()=>this.ui.open('powerups');document.querySelector('#home-campaign').onclick=()=>this.ui.open('journal');document.querySelector('#home-voices').onclick=()=>this.ui.open('voices');document.querySelector('#pause-game').onclick=()=>this.ui.open('journal');document.querySelector('#open-journal').onclick=()=>this.ui.open('equipment');document.querySelector('.brand').onclick=e=>{e.preventDefault();if(this.playing)this.ui.open('settings');};this.audioToggles=new AudioToggles(this);this.touchGuard=new GameTouchGuard(()=>this.playing);this.updateSound();this.refreshContinue();document.querySelectorAll('[data-home-control]').forEach(button=>button.onclick=()=>{const action=button.dataset.homeControl;if(action==='play')this.start(false);else if(action==='map')this.journey.open();else {const ids=Object.keys(MISSIONS).map(Number),i=ids.indexOf(this.selectedMission),next=(i+(action==='next'?1:-1)+ids.length)%ids.length;this.journey.select(ids[next]);}});document.addEventListener('visibilitychange',()=>{if(document.hidden&&this.playing&&!this.ui.dialog.open)this.ui.open('journal');});}
 updateSound(){this.music?.tick();this.audioToggles?.render();}
 refreshContinue(){this.journey.refresh(true);}
 start(resume,missionId,hub=false){const requested=Number(resume?this.save.load()?.mission??this.selectedMission:missionId||this.selectedMission);if(!hub&&!canPlayMission(requested,this.save.completed(),this.settings?.unlockAllMissions)){this.journey.renderSelection(requested);this.ui.toast(lockedMessage(requested,this.save.completed()));return false;}if(missionId)this.selectedMission=Number(missionId);this.audio.unlock();this.audio.stop();this.pendingRun=hub?{hub:true,campaign:this.save.load()}:resume?this.save.load():null;if(this.pendingRun&&!hub)this.selectedMission=this.pendingRun.mission;this.journey.select(this.selectedMission);if(this.pendingRun?.complete){this.selectedMission=this.pendingRun.mission;this.pendingRun=null;}this.playing=true;document.body.classList.add('is-playing');document.querySelector('#home').classList.add('hidden');document.querySelector('#play').classList.remove('hidden');window.scrollTo({top:0,behavior:'instant'});if(!window.Phaser){document.querySelector('#game-canvas').textContent='Il motore non si è caricato. Ricarica la pagina.';return;}if(!this.game){const scene=new GameScene(this);this.game=new Phaser.Game({type:Phaser.AUTO,parent:'game-canvas',width:960,height:560,pixelArt:true,antialias:false,backgroundColor:'#1e353d',scale:{mode:Phaser.Scale.FIT,autoCenter:Phaser.Scale.CENTER_BOTH},scene:[scene],audio:{noAudio:true},banner:false});}else{this.scene.scene.resume();this.scene.beginRun(this.pendingRun);this.game.scale.refresh();}this.fullscreen.sync();}
 goHome(){this.raceControls?.setActive(false);this.scene?.revival?.cancel();this.music?.silence();this.scene?.adventureController?.save();this.scene?.facilityController?.save();this.scene?.zoneController?.save();this.bus.emit("zone:loaded");this.bus.emit("dialogue:cancel");this.bus.emit("loot:clear");this.playing=false;void this.fullscreen.exit();document.body.classList.remove('is-playing');this.input.enabled=false;this.input.clear();this.audio.stop();this.scene?.scene.pause();document.querySelector('#play').classList.add('hidden');document.querySelector('#home').classList.remove('hidden');document.querySelector('#chapter-card').classList.add('hidden');this.refreshContinue();window.scrollTo({top:0,behavior:'instant'});}
}
if(typeof window!=='undefined')new ClickGame().init().catch(error=>{console.error(error);document.querySelector('#campaign-heading').textContent='Impossibile avviare il gioco in questa sessione. Prova a ricaricare la pagina.';});
